  "Follow saves this account on this device. Add it to feeds.config.json and sync before its posts join the home timeline.": "«Читать» сохраняет этот аккаунт на устройстве. Добавьте его в feeds.config.json и синхронизируйте, чтобы посты попали в ленту.",
