  "Find accounts to follow": "Найти аккаунты для подписки",
  "Add a photo and bio from Edit profile. Posts here come from feeds you follow.": "Добавьте фото и биографию через «Изменить профиль». Посты здесь берутся из лент, которые вы читаете.",
  "Language and appearance stay on this device.": "Язык и оформление остаются на этом устройстве.",
