  "This app is a reader for posts from feeds you follow. Not affiliated with X.": "Это читалка постов из лент, которые вы читаете. Не связано с X.",
  "Sign in with the 16-digit account number from sign-up. It is shown once. There is no password to reset.": "Входите по 16-значному номеру аккаунта с регистрации. Он показывается один раз. Пароль сбросить нельзя.",
  "The account number is your login. The timeline shows posts from feeds. Not affiliated with X.": "Номер аккаунта — это вход. В ленте посты из источников. Не связано с X.",
  "The account number is stored as a hash. There is no email on the account. Settings stay on this device.": "Номер аккаунта хранится как хеш. У аккаунта нет почты. Настройки остаются на этом устройстве.",
  "This app does not use tracking cookies. The session and settings stay in this browser.": "Это приложение не использует следящие cookie. Сессия и настройки остаются в этом браузере.",
