  "Messages you post here go out from the spare account, one tap at a time.": "Сообщения отсюда уходят с запасного аккаунта, по одному на нажатие.",
  "Not sent.": "Не отправлено.",
  "One message at a time. Try again in a moment.": "По одному сообщению. Попробуйте через мгновение.",
  "Opening…": "Открываем…",
  "Sending…": "Отправка…",
  "Solve it yourself to send your message. Nothing solves it for you.": "Решите проверку сами, чтобы отправить сообщение. Никто не решает её за вас.",
  "Start a direct message with this person from the spare account.": "Начните личную переписку с этим человеком с запасного аккаунта.",
  "That’s a lot of messages this minute. You can send again in {n} seconds.": "Много сообщений за эту минуту. Снова отправить можно через {n} с.",
  "The check couldn’t load here. Send this message in the Discord app instead.": "Проверка здесь не загрузилась. Отправьте это сообщение в приложении Discord.",
  "This account can’t send messages here.": "Этот аккаунт не может отправлять сюда сообщения.",
  "Wait {n} seconds before opening another chat.": "Подождите {n} с, прежде чем открыть ещё один чат.",
  "You can read and send messages here as the spare account. Every message is one you type and send yourself. Discord may flag automated or self-bot use, so keep it to a spare account.": "Здесь можно читать и отправлять сообщения от имени запасного аккаунта. Каждое сообщение вы пишете и отправляете сами. Discord может пометить автоматизацию или self-bot, поэтому используйте только запасной аккаунт.",
  "Paste keys from your own accounts. They stay encrypted, and the saved value is never shown again.": "Вставьте ключи своих аккаунтов. Они хранятся в зашифрованном виде, и сохранённое значение больше не показывается.",
  "Keys from your own accounts stay encrypted.": "Ключи ваших аккаунтов хранятся в зашифрованном виде.",
  "In your own browser, while you are signed in, export cookies as a Netscape cookies.txt file or copy the Cookie header from one request you made to that site.": "В своём браузере, пока вы вошли в аккаунт, экспортируйте cookies в файл Netscape cookies.txt или скопируйте заголовок Cookie из одного своего запроса к этому сайту.",
  "Paste a Cookie header or a Netscape cookies.txt file.": "Вставьте заголовок Cookie или файл Netscape cookies.txt.",
  "Paste the client id and the client secret from your own app, one on each line.": "Вставьте идентификатор клиента и секрет клиента своего приложения, каждый с новой строки.",
  "Paste the token from your own account.": "Вставьте токен своего аккаунта.",
