  "This permanently deletes this account. Your profile, photos, sessions, follows, followers, friends, notification tabs, feed settings, groups, drafts, likes, bookmarks, watch history, community posts, vault, drive files, linked accounts, and uploads are removed. The handle can stay reserved so nobody else can take it. This cannot be undone.": "Это навсегда удаляет аккаунт. Профиль, фото, сессии, подписки, подписчики, друзья, вкладки уведомлений, настройки ленты, группы, черновики, отметки «нравится», закладки, история просмотра, посты в сообществах, сейф, файлы диска, привязанные аккаунты и загрузки будут удалены. Имя может остаться занятым, чтобы его не занял кто-то другой. Это нельзя отменить.",
