  "Max": "Максимум",
  "Light does less and leaves feeds, search, and translation on the server.": "Лёгкий режим делает меньше и оставляет ленты, поиск и перевод на сервере.",
  "Balanced is the default. This device does the work it can, and the server covers the rest.": "Сбалансированный режим включён по умолчанию. Устройство делает то, что может, а остальное остаётся серверу.",
