  "Remove this passkey?": "Удалить этот ключ доступа?",
  "A passkey uses this device's fingerprint, face, or screen lock. No password is required. The account number still works as an optional backup.": "Ключ доступа использует отпечаток, лицо или блокировку экрана этого устройства. Пароль не нужен. Номер счёта остаётся необязательной запасной дверью.",
  "Passkeys stay on the site where you created them. A passkey made on one site does not sign in on the other.": "Ключи доступа остаются на том сайте, где вы их создали. Ключ одного сайта не входит на другом.",
