  "Summaries on this device": "Краткий пересказ на этом устройстве",
  "Included. No download. Long posts, threads, unread messages, and Catch me up use this device first.": "Уже в приложении. Без загрузки. Длинные посты, ветки, непрочитанные сообщения и «Что нового» сначала обрабатываются здесь.",
  "Compose help on this device": "Помощь при написании на этом устройстве",
  "Included. No download. Suggestions, grammar, and tone stay here unless you allow a server.": "Уже в приложении. Без загрузки. Подсказки, грамматика и тон остаются здесь, пока вы не разрешите сервер.",
  "Search saved posts by meaning": "Искать сохранённые посты по смыслу",
  "Off until you turn it on. The included ranker needs no download.": "Выключено, пока вы не включите. Встроенный поиск не требует загрузки.",
  "Download a search model": "Скачать модель поиска",
  "About {size}. Apache-2.0. Off until you turn it on.": "Около {size}. Apache-2.0. Выключено, пока вы не включите.",
