  "Download a translation model": "Скачать модель перевода",
  "About {size} for a language pair. Off until you turn it on. OPUS-MT is CC-BY-4.0.": "Около {size} на пару языков. Выключено, пока вы не включите. OPUS-MT — CC-BY-4.0.",
  "Auto-translate direct messages": "Автоперевод личных сообщений",
