  "{n} reactions": "Реакций: {n}",
  "Smart Auto: media from sites that are blocked in your country, or that failed to load on this device, comes through our servers. Photos and videos keep their original quality.": "Умный авто: фото и видео с сайтов, заблокированных в вашей стране или не загрузившихся на этом устройстве, идут через наши серверы. Качество остаётся исходным.",
  "{ms} ms": "{ms} мс",
  "not reachable": "недоступен",
  "If the app is slow or won't load": "Если приложение тормозит или не загружается",
  "The app keeps your feed on this device, so saved posts open even with a bad connection. When our main server stalls, it switches to the backup server by itself.": "Приложение хранит ленту на этом устройстве, поэтому сохранённые посты открываются даже при плохой связи. Если основной сервер зависает, приложение само переключается на резервный.",
  "Checking…": "Проверяем…",
  "Check connection": "Проверить соединение",
  "In India": "В Индии",
  "Some internet providers block sites through DNS. Turning on secure DNS usually fixes it:": "Некоторые провайдеры блокируют сайты через DNS. Обычно помогает включить защищённый DNS:",
  "Android: Settings > Network & internet > Private DNS > enter dns.google or one.one.one.one": "Android: Настройки > Сеть и интернет > Персональный DNS-сервер > введите dns.google или one.one.one.one",
  "Chrome or Edge: Settings > Privacy and security > Use secure DNS": "Chrome или Edge: Настройки > Конфиденциальность и безопасность > Использовать безопасный DNS",
  "Firefox: Settings > Privacy & Security > DNS over HTTPS > Increased protection": "Firefox: Настройки > Приватность и защита > DNS через HTTPS > Повышенная защита",
  "iPhone: install a secure DNS app such as Cloudflare 1.1.1.1": "iPhone: установите приложение защищённого DNS, например Cloudflare 1.1.1.1",
  "In Russia": "В России",
  "Smart Auto sends blocked photos and videos through our own servers, and friends who already have a post can pass it to you directly (peer sharing). This helps, but some blocks can't be avoided without a VPN, so we can't promise everything will load.": "Умный авто пропускает заблокированные фото и видео через наши собственные серверы, а друзья, у которых пост уже есть, могут передать его вам напрямую (обмен между устройствами). Это помогает, но некоторые блокировки без VPN не обойти, поэтому мы не можем обещать, что загрузится всё.",
  "Main server": "Основной сервер",
  "Backup server": "Резервный сервер",
  "Server {n}": "Сервер {n}",
  "Connection is slow - showing saved posts": "Медленное соединение — показываем сохранённые посты",
  "Help": "Помощь",
  "All settings": "Все настройки",
  "Blue": "Синий",
  "Choices apply right away and follow your account to your other devices.": "Изменения применяются сразу и переходят на другие ваши устройства.",
