  "Automatic (busy account)": "Автоматически (очень активный аккаунт)",
  "Hides replies to other people and shows up to 3 posts every 2 hours when the account posts a lot": "Если аккаунт публикует очень много, скрывает его ответы другим и показывает не больше 3 постов за 2 часа",
