  "By likes and reposts": "По лайкам и репостам",
  "One grouped card a day": "Одна общая карточка в день",
  "Folded posts load nothing until you open them. Your choice follows your account.": "Свёрнутые посты ничего не загружают, пока вы их не откроете. Выбор сохраняется в вашем аккаунте.",
  "Muted for now. Change it any time in Posting volume.": "Пока скрыто. Изменить можно в любой момент в разделе «Частота постов».",
  "Unmuted": "Снова показывается",
  "+{n} more at 10 different people · up to {cap} a day": "+{n} ещё при 10 разных людях · до {cap} в день",
  "+{n} once": "+{n} один раз",
  "+{n} once they stay a week, post and keep a streak · up to {cap} a day": "+{n}, когда приглашённый пробудет неделю, опубликует пост и сохранит серию · до {cap} в день",
  "+{n} when 3 different people reply or like · up to {cap} a day": "+{n}, когда 3 разных человека ответят или поставят лайк · до {cap} в день",
  "A gift paid with money stays wrapped until the recipient opens it. You can ask for a refund of an unopened gift within {n} days. Once it is opened, it can’t be refunded.": "Подарок, оплаченный деньгами, остаётся в упаковке, пока получатель его не откроет. Вернуть деньги за неоткрытый подарок можно в течение {n} дней. Открытый подарок вернуть нельзя.",
  "A popular post": "Популярный пост",
  "A quality post": "Качественный пост",
  "Amount": "Количество",
  "An invite who became active": "Приглашённый стал активным",
  "Badge reward": "Награда за значок",
  "Bought a sticker pack": "Куплен набор стикеров",
  "Bought stickers work in Messages and in comments.": "Купленные стикеры работают в сообщениях и комментариях.",
  "Buy": "Купить",
  "Buy for me": "Купить себе",
  "Card details go straight to the payment provider. ViktorychApp never sees or stores them.": "Данные карты передаются напрямую платёжному провайдеру. ViktorychApp их не видит и не хранит.",
  "Card payments are coming soon. You can already pay with Viktorychs.": "Оплата картой скоро появится. Уже сейчас можно платить Viktorychs.",
  "Card, Apple Pay or Google Pay": "Карта, Apple Pay или Google Pay",
  "Coming soon": "Скоро",
  "Couldn’t do that.": "Не получилось.",
  "Free for everyone": "Бесплатно для всех",
  "Get": "Получить",
  "Gift stickers": "Подарить стикеры",
  "Gifts and sticker packs are digital items for use inside ViktorychApp. They have no cash value.": "Подарки и наборы стикеров — цифровые предметы для использования внутри ViktorychApp. Они не имеют денежной стоимости.",
  "Gifts, stickers and purchases": "Подарки, стикеры и покупки",
  "Grant": "Выдать",
  "Grant Viktorychs": "Выдать Viktorychs",
  "Grant a test item": "Выдать тестовый предмет",
  "Granted by the app owner": "Выдано владельцем приложения",
  "I agree to the purchase terms and want it delivered now. I understand the {n}-day right to cancel ends at delivery.": "Я принимаю условия покупки и хочу получить товар сейчас. Я понимаю, что право на отказ в течение {n} дней заканчивается при получении.",
  "I agree to the purchase terms. An unopened gift can be refunded within {n} days.": "Я принимаю условия покупки. За неоткрытый подарок можно вернуть деньги в течение {n} дней.",
  "Item": "Предмет",
  "Items can’t be resold, traded for money or exchanged for cash.": "Предметы нельзя перепродавать, обменивать на деньги или выводить в наличные.",
  "Limited": "Лимитировано",
  "Limited editions": "Лимитированные выпуски",
  "More sticker packs": "Больше наборов стикеров",
  "My purchases": "Мои покупки",
  "No purchases yet": "Покупок пока нет",
  "No. {n}": "№ {n}",
  "Only people other than you count, and their accounts must be at least a week old. New accounts start earning after 3 days. Daily caps apply.": "Учитываются только другие люди, и их аккаунтам должно быть не меньше недели. Новые аккаунты начинают получать награды через 3 дня. Действуют дневные лимиты.",
  "Only the app owner can use these tools.": "Эти инструменты доступны только владельцу приложения.",
  "Open gift": "Открыть подарок",
  "Opened": "Открыт",
