  "Owner tools": "Инструменты владельца",
  "Pay with": "Оплатить",
  "Pay {price}": "Оплатить {price}",
  "Please accept the purchase terms.": "Примите условия покупки.",
  "Purchase terms": "Условия покупки",
  "Refund": "Вернуть деньги",
  "Refundable until {date} while unopened": "Можно вернуть до {date}, пока не открыт",
  "Send as gift": "Отправить в подарок",
  "Sign in to see your purchases.": "Войдите, чтобы увидеть покупки.",
  "Sold out": "Распродано",
  "Sticker": "Стикер",
  "Sticker packs": "Наборы стикеров",
  "Sticker packs and items you buy for yourself are delivered right away. By asking for that, you agree that the {n}-day right to cancel ends at delivery.": "Наборы стикеров и предметы, купленные для себя, доставляются сразу. Запрашивая это, вы соглашаетесь, что право на отказ в течение {n} дней заканчивается при получении.",
  "Streak milestones: {list}": "Этапы серии: {list}",
  "Thank you! Your item is delivered as soon as the payment is confirmed.": "Спасибо! Предмет будет доставлен, как только платёж подтвердится.",
  "The payment page couldn’t open. Try again later.": "Не удалось открыть страницу оплаты. Попробуйте позже.",
  "They already have this sticker pack.": "У этого человека уже есть этот набор стикеров.",
  "This item can only be bought with money.": "Этот предмет можно купить только за деньги.",
  "This limited edition has ended.": "Этот лимитированный выпуск закончился.",
  "This person isn’t accepting gifts from you.": "Этот человек не принимает от вас подарки.",
  "Too many gifts right now. Try again later.": "Слишком много подарков. Попробуйте позже.",
  "Viktorychs are earned by real effort and are never sold. They have no cash value and can only be spent on gifts and stickers.": "Viktorychs зарабатываются реальными усилиями и никогда не продаются. Они не имеют денежной стоимости, и их можно тратить только на подарки и стикеры.",
  "Viktorychs earned through abuse, such as fake accounts or self-engagement, can be removed.": "Viktorychs, полученные нечестно, например через фейковые аккаунты или накрутку себе, могут быть списаны.",
  "Viktorychs have no cash value and can’t be refunded once spent.": "Viktorychs не имеют денежной стоимости и не возвращаются после траты.",
  "Viktorychs have no cash value. They can’t be bought, cashed out or transferred for money, and they can’t be refunded once spent.": "Viktorychs не имеют денежной стоимости. Их нельзя купить, вывести или передать за деньги, и они не возвращаются после траты.",
  "Waiting for payment": "Ожидает оплаты",
  "Wrapped gift": "Подарок в упаковке",
  "You already have this sticker pack.": "У вас уже есть этот набор стикеров.",
  "You can pay for an item with money, through our payment provider, or with Viktorychs. Viktorychs are earned by taking part and are never sold.": "Оплатить предмет можно деньгами через нашего платёжного провайдера или Viktorychs. Viktorychs зарабатываются участием и никогда не продаются.",
  "You can’t send gifts to someone who blocked you or who doesn’t accept gifts from you. Gifting is rate-limited to stop spam.": "Нельзя дарить подарки тому, кто вас заблокировал или не принимает от вас подарки. Количество подарков ограничено, чтобы не было спама.",
  "You can’t send gifts to this account.": "Этому аккаунту нельзя дарить подарки.",
  "{d} days +{n}": "{d} дн. +{n}",
  "{n} left": "Осталось {n}",
  "{n} stickers": "Стикеров: {n}",
