  "Same person as {name}?": "Это тот же человек, что и {name}?",
  "Undo": "Отменить",
  "Unmerged. Each account has its own profile again.": "Разъединено. У каждого аккаунта снова свой профиль.",
  "Merged profiles": "Объединённые профили",
  "Achievement unlocked": "Достижение получено",
  "Achievements": "Достижения",
  "A short animation plays when you earn a badge.": "Когда вы получаете значок, показывается короткая анимация.",
  "Preview achievement": "Показать пример достижения",
