  "Send to my TV": "Отправить на мой ТВ",
  "Open the app on your TV without typing a long address. It's free and takes about a minute.": "Откройте приложение на телевизоре, не вводя длинный адрес. Это бесплатно и занимает около минуты.",
  "Your TV link": "Ваша ссылка для ТВ",
