  "Copy TV link": "Скопировать ссылку для ТВ",
  "Which TV do you have?": "Какой у вас телевизор?",
  "Pick your TV to see the fastest way for it.": "Выберите свой телевизор, чтобы увидеть самый быстрый способ для него.",
  "After the first time": "После первого раза",
  "Bookmark the page in the TV browser, or pin it to the TV home screen. On Google TV and Android TV you can also install our TV app for its own icon.": "Добавьте страницу в закладки браузера ТВ или закрепите её на главном экране. На Google TV и Android TV можно также установить наше приложение для ТВ со своим значком.",
  "What a website can't do": "Чего не может сайт",
  "Find your TV on the Wi-Fi and open its browser by itself. Only the TV maker's app can do that, which is why the steps use it.": "Сам найти телевизор в сети Wi-Fi и открыть на нём браузер. Это умеет только приложение производителя ТВ, поэтому шаги используют его.",
  "Screen mirroring (Smart View, AirPlay) only copies your phone's screen. It doesn't open the TV browser.": "Повтор экрана (Smart View, AirPlay) только показывает экран телефона. Браузер ТВ он не открывает.",
  "One-tap casting needs a paid Google registration, so we don't use it.": "Трансляция в одно касание требует платной регистрации в Google, поэтому мы её не используем.",
  "Copied. Now paste it on the TV with the steps below.": "Скопировано. Теперь вставьте ссылку на телевизоре по шагам ниже.",
