  "Check your connection and try again.": "Проверьте подключение и попробуйте снова.",
  "SMSPool isn't connected": "SMSPool не подключён",
  "Add your SMSPool API key as the Worker secret SMSPOOL_API_KEY. Codes show up here after that.": "Добавьте ключ API SMSPool как секрет Worker SMSPOOL_API_KEY. После этого коды появятся здесь.",
