  "No SMS arrived. The order was refunded.": "SMS не пришло. Заказ возвращён.",
  "The order was cancelled.": "Заказ отменён.",
  "No SMS arrived before the number expired.": "SMS не пришло до истечения срока номера.",
  "Expires in {time}": "Истекает через {time}",
  "No messages yet.": "Сообщений пока нет.",
  "until {date}": "до {date}",
  "Mail": "Почта",
  "Open Yandex Mail settings › Mail clients and turn on IMAP (portal password or app password).": "Откройте настройки Яндекс Почты › Почтовые программы и включите IMAP (пароль портала или пароль приложения).",
  "Open Yandex ID › Security › App passwords, choose Mail, name it ViktorychApp and copy the password.": "Откройте Яндекс ID › Безопасность › Пароли приложений, выберите «Почта», назовите ViktorychApp и скопируйте пароль.",
  "Create a folder named ViktorychApp.": "Создайте папку ViktorychApp.",
  "Settings › Message filtering › Create filter, then paste the rule below.": "Настройки › Правила обработки писем › Создать правило, затем вставьте правило ниже.",
  "If: From contains \"simplelogin\"\nOr: To contains \"@{alias-domain}\"\nThen: Move to folder \"ViktorychApp\"\nApply to existing messages: on": "Если: «От кого» содержит \"simplelogin\"\nИли: «Кому» содержит \"@{alias-domain}\"\nТо: Положить в папку \"ViktorychApp\"\nПрименить к существующим письмам: да",
  "Turn on 2-Step Verification for your Google account (app passwords need it).": "Включите двухэтапную аутентификацию в аккаунте Google (без неё нет паролей приложений).",
  "Open Google Account › App passwords, name it ViktorychApp and copy the 16-letter password.": "Откройте Аккаунт Google › Пароли приложений, назовите ViktorychApp и скопируйте пароль из 16 букв.",
  "Create a label named ViktorychApp. In IMAP a label is a folder.": "Создайте ярлык ViktorychApp. В IMAP ярлык — это папка.",
  "Settings › Filters › Create a new filter, paste the search below, then choose Skip the Inbox and Apply the label ViktorychApp.": "Настройки › Фильтры › Создать фильтр, вставьте запрос ниже, затем выберите «Пропустить входящие» и «Применить ярлык ViktorychApp».",
  "Turn on two-step verification for your Microsoft account.": "Включите двухшаговую проверку в учётной записи Microsoft.",
  "Open Security › App passwords and create one. Some Outlook.com accounts no longer allow IMAP with an app password; if the test fails, use Yandex or Gmail.": "Откройте Безопасность › Пароли приложений и создайте пароль. Некоторые аккаунты Outlook.com больше не пускают IMAP по паролю приложения; если проверка не пройдёт, используйте Яндекс или Gmail.",
  "Settings › Mail › Rules › Add new rule, then use the rule below.": "Параметры › Почта › Правила › Добавить правило, затем используйте правило ниже.",
  "Condition: From includes \"simplelogin\"\nAction: Move to \"ViktorychApp\"\nStop processing more rules: on": "Условие: «От» содержит \"simplelogin\"\nДействие: Переместить в \"ViktorychApp\"\nПрекратить обработку других правил: да",
  "Open Settings › Mail programs and allow IMAP access.": "Откройте Настройки › Почтовые программы и разрешите доступ по IMAP.",
  "Open Security › Passwords for external apps, create one for ViktorychApp and copy it.": "Откройте Безопасность › Пароли для внешних приложений, создайте пароль для ViktorychApp и скопируйте его.",
  "Settings › Filters › Add filter, then use the rule below.": "Настройки › Фильтры › Добавить фильтр, затем используйте правило ниже.",
  "If: From contains \"simplelogin\"\nThen: Move to folder \"ViktorychApp\"": "Если: «От» содержит \"simplelogin\"\nТо: Переместить в папку \"ViktorychApp\"",
  "The mailbox refused the email or app password.": "Почтовый ящик не принял адрес или пароль приложения.",
  "That folder doesn't exist. Check the name, including capital letters.": "Такой папки нет. Проверьте название, включая заглавные буквы.",
  "Pick a dedicated folder. INBOX needs the extra switch below.": "Выберите отдельную папку. Для INBOX нужен дополнительный переключатель ниже.",
  "Too many checks. Trying again shortly.": "Слишком много проверок. Скоро попробуем снова.",
  "Mail isn't available yet.": "Почта пока недоступна.",
  "Sign in to use Mail.": "Войдите, чтобы пользоваться Почтой.",
  "The mailbox took too long to answer.": "Почтовый ящик слишком долго не отвечал.",
  "Check the fields and try again.": "Проверьте поля и попробуйте снова.",
  "Couldn't reach the mailbox.": "Не удалось связаться с почтовым ящиком.",
  "Connected": "Подключено",
  "Add to Inbox": "Добавить во Входящие",
  "One folder of your own mailbox, read-only, with codes highlighted.": "Одна папка вашего ящика, только чтение, коды подсвечены.",
  "SMSPool": "SMSPool",
  "Codes from your own SMSPool numbers.": "Коды с ваших номеров SMSPool.",
