  "What the app can see": "Что видит приложение",
  "Only the one folder you choose (we suggest a new folder named ViktorychApp).": "Только одну выбранную вами папку (советуем новую папку ViktorychApp).",
  "The sender, subject and date of messages in that folder.": "Отправителя, тему и дату писем в этой папке.",
