  "Your app password is kept encrypted on this device. It passes through our relay only for each check, and the relay keeps nothing.": "Пароль приложения хранится зашифрованным на этом устройстве. Он проходит через наш ретранслятор только при каждой проверке, и ретранслятор ничего не сохраняет.",
