  "Mail to an alias forwards to your own mailbox. Your Mail filter can then move code emails into your ViktorychApp folder.": "Письма на псевдоним пересылаются в ваш ящик. Ваш фильтр почты затем переносит письма с кодами в папку ViktorychApp.",
