  "Phones may still stop YouTube in the background; iPhone and iPad always do. Lyrics aren’t shown: there is no free licensed source.": "Телефоны всё равно могут останавливать YouTube в фоне, а iPhone и iPad делают это всегда. Тексты песен не показываются: бесплатного лицензированного источника нет.",
