  "Sign in to YouTube": "Войти в YouTube",
  "Sign in to YouTube for Premium: no ads, 256 kbps audio and the best quality your account allows.": "Войдите в YouTube, чтобы получить Premium: без рекламы, звук 256 кбит/с и лучшее качество, доступное аккаунту.",
  "Sleep": "Сон",
