  "Songs, artists, albums and playlists. Our own songs show first.": "Песни, исполнители, альбомы и плейлисты. Наши песни показываются первыми.",
  "Spotify playlist link": "Ссылка на плейлист Spotify",
  "Starting radio": "Запускаем радио",
  "Tap the heart on any YouTube song to keep it here. Likes and playlists follow your account to every device.": "Нажмите на сердечко у любой песни с YouTube, чтобы сохранить её здесь. Лайки и плейлисты доступны на всех устройствах аккаунта.",
  "The queue ends after this song.": "Очередь закончится после этой песни.",
  "This browser keeps the YouTube sign-in out of other sites, so the player may show ads and lower quality. Open it in Chrome, Edge or Firefox for your Premium.": "Этот браузер не передаёт вход в YouTube другим сайтам, поэтому возможны реклама и более низкое качество. Откройте в Chrome, Edge или Firefox, чтобы работал Premium.",
