  "Auto saves data on slow networks, Data Saver and low battery. Data saving loads notes only for posts on screen.": "«Авто» экономит трафик в медленной сети, в режиме экономии и при низком заряде. В режиме экономии заметки загружаются только для постов на экране.",
  "Ban writer from notes": "Запретить автору заметки",
