  "Community Notes": "Заметки сообщества",
  "Community Notes add helpful context to posts that might be misleading. Contributors write and rate notes, and a note is shown only when people who usually disagree both find it helpful.": "Заметки сообщества добавляют полезный контекст к постам, которые могут вводить в заблуждение. Участники пишут и оценивают заметки, а заметка показывается, только когда её считают полезной люди, которые обычно не согласны друг с другом.",
  "Context is written by people who use Viktorych, and appears when rated helpful by others.": "Контекст пишут пользователи Viktorych; он появляется, когда другие считают его полезным.",
  "Currently not rated helpful": "Сейчас не считается полезной",
