  "I already have a key": "У меня уже есть ключ",
  "Step 1 · Open Discord": "Шаг 1 · Откройте Discord",
  "Sign in with a SPARE account, not your main one. Discord may lock accounts used this way.": "Войдите в ЗАПАСНОЙ аккаунт, не в основной. Discord может блокировать аккаунты, используемые так.",
  "Open Discord": "Открыть Discord",
  "I'm signed in": "Я вошёл",
  "Step 2 · Copy your key": "Шаг 2 · Скопируйте ключ",
  "This step needs a desktop browser. Open this page on a computer to copy the key, or paste a key you already have.": "Для этого шага нужен браузер на компьютере. Откройте эту страницу на компьютере, чтобы скопировать ключ, или вставьте уже имеющийся.",
  "In the Discord tab, open the developer console: F12, or Ctrl+Shift+I (Cmd+Option+I on a Mac).": "Во вкладке Discord откройте консоль разработчика: F12 или Ctrl+Shift+I (Cmd+Option+I на Mac).",
  "Copy the snippet below, paste it into the console and press Enter.": "Скопируйте фрагмент ниже, вставьте его в консоль и нажмите Enter.",
  "It copies your key to the clipboard. Come back here and paste it in the next step.": "Он копирует ваш ключ в буфер. Вернитесь сюда и вставьте его на следующем шаге.",
  "What it does: it reads your own account's key and copies it to your clipboard. It is not sent anywhere.": "Что делает: читает ключ вашего аккаунта и копирует его в буфер. Никуда не отправляется.",
  "Console snippet": "Фрагмент для консоли",
  "Copy snippet": "Скопировать фрагмент",
  "Discord will show a red “Self-XSS” warning.": "Discord покажет красное предупреждение «Self-XSS».",
  "That warning is there because pasting code someone else gives you can hand them your account. This snippet is safe only because you can read exactly what it does above. Never paste code you do not understand.": "Это предупреждение есть потому, что вставка чужого кода может отдать им ваш аккаунт. Этот фрагмент безопасен только потому, что вы можете прочитать, что он делает выше. Никогда не вставляйте код, который не понимаете.",
  "Step 3 · Paste your key": "Шаг 3 · Вставьте ключ",
