  "NZlay account": "Аккаунт NZlay",
  "NZlay didn’t accept that email and password.": "NZlay не принял эту почту и пароль.",
  "NZlay doesn’t let this account post here.": "NZlay не разрешает этой учётной записи здесь публиковать.",
