  "NZlay forum posting": "Публикация на форуме NZlay",
  "NZlay has no sign-in for other apps, so you sign in with your NZlay email and password here. Your password goes once to NZlay and is never kept. The NZlay session that comes back is encrypted and kept only in this browser. Posts go out only when you tap Post or Reply.": "У NZlay нет входа для других приложений, поэтому здесь вы входите с почтой и паролем NZlay. Пароль отправляется в NZlay один раз и никогда не сохраняется. Полученный сеанс NZlay шифруется и хранится только в этом браузере. Публикации отправляются только когда вы нажимаете «Опубликовать» или «Ответить».",
  "NZlay isn’t answering right now.": "NZlay сейчас не отвечает.",
  "NZlay member": "Участник NZlay",
