  "Signs you out here and removes everything this app saved in this browser. Your account and posts stay on the server.": "Выполняет выход здесь и удаляет всё, что приложение сохранило в этом браузере. Ваш аккаунт и посты остаются на сервере.",
  "Delete this app's data from your browser": "Удаление данных приложения из браузера",
  "Chrome on Android:": "Chrome на Android:",
  "Settings → Site settings → All sites → this site → Clear & reset.": "Настройки → Настройки сайтов → Все сайты → этот сайт → Очистить и сбросить.",
  "iPhone and iPad:": "iPhone и iPad:",
  "Deleting the Home Screen app removes its data. In Safari, also use Settings → Apps → Safari → Advanced → Website Data.": "Удаление приложения с экрана «Домой» удаляет его данные. В Safari также откройте Настройки → Приложения → Safari → Дополнения → Данные сайтов.",
  "Chrome or Edge on a computer:": "Chrome или Edge на компьютере:",
  "Click the icon left of the address, then Site settings → Delete data.": "Нажмите значок слева от адреса, затем Настройки сайтов → Удалить данные.",
  "Firefox:": "Firefox:",
  "Click the lock icon in the address bar, then Clear cookies and site data.": "Нажмите значок замка в адресной строке, затем Удалить куки и данные сайта.",
  "Safari on Mac:": "Safari на Mac:",
  "Safari → Settings → Privacy → Manage Website Data → this site → Remove.": "Safari → Настройки → Конфиденциальность → Управлять данными веб-сайтов → этот сайт → Удалить.",
  "This browser doesn't report how much is stored.": "Этот браузер не сообщает, сколько данных хранится.",
  "Stored on this device: {used} of {quota} available": "Хранится на этом устройстве: {used} из {quota} доступных",
