  "Only you add sources. Allow lets it in, Block says no for now, Ban stops it for good and removes copies.": "Только вы добавляете источники. «Разрешить» впускает его, «Заблокировать» — отказ на сейчас, «Запретить» — навсегда и с удалением копий.",
