  "Kept for when you turn Friends back on.": "Сохранятся до повторного включения «Друзей».",
  "Lets each person turn Friends off: no friend requests, no friends lists, counts or online status.": "Позволяет каждому отключить «Друзей»: без запросов в друзья, списков, счётчиков и статуса в сети.",
  "Nobody can send you friend requests, and friend features are hidden for you. Turn it back on any time.": "Никто не сможет отправлять вам запросы в друзья, а функции друзей будут скрыты. Включить снова можно в любой момент.",
